# Initially generated by GitHub Copilot.
import unittest

from py_misc import json_snippet_browser


class TestJsonSnippetBrowser(unittest.TestCase):
    def test_multistep_zoom_uses_per_span_base_size(self):
        html = json_snippet_browser._build_multistep_html(
            json_text='{"a": "יְ", "b": "ABC"}',
            steps=[{"highlight_text": '"יְ"'}],
            top_rgb=(13, 94, 87),
            bot_rgb=(8, 61, 56),
            font_size_px=34,
            pointed_scale=1.5,
            companion_html="",
        )

        self.assertIn(
            "font-size: calc(var(--base-size-px) * 2) !important;",
            html,
        )
        self.assertNotIn("font-size: 102px !important;", html)
        self.assertIn("--base-size-px:51px", html)
        self.assertIn("--base-size-px:34px", html)
        self.assertIn('body[data-step="0"] #main .hl-0', html)
        self.assertIn('body[data-step="0"] #zoom .zm-0', html)

    def test_single_span_zoom_modulates_pointed_and_plain_text(self):
        pointed_zoom = json_snippet_browser._one_span(
            value="יְ",
            color="#ce9178",
            font_size_px=34,
            pointed_scale=1.5,
            hl_bg=False,
            zoom=True,
        )
        plain_zoom = json_snippet_browser._one_span(
            value="ABC",
            color="#ce9178",
            font_size_px=34,
            pointed_scale=1.5,
            hl_bg=False,
            zoom=True,
        )

        self.assertIn("--base-size-px:51px", pointed_zoom)
        self.assertIn("font-size:102px", pointed_zoom)
        self.assertIn("--base-size-px:34px", plain_zoom)
        self.assertIn("font-size:68px", plain_zoom)

    def test_multistep_html_includes_arrow_key_navigation(self):
        html = json_snippet_browser._build_multistep_html(
            json_text='["a", "b"]',
            steps=[
                {"highlight_text": '"a"'},
                {"highlight_text": '"b"'},
            ],
            top_rgb=(13, 94, 87),
            bot_rgb=(8, 61, 56),
            font_size_px=34,
            pointed_scale=1.5,
            companion_html="",
        )

        self.assertIn("var MAX_STEP = 1;", html)
        self.assertIn("event.key === 'ArrowLeft'", html)
        self.assertIn("event.key === 'ArrowRight'", html)
        self.assertIn("function moveStepBy(delta)", html)


if __name__ == "__main__":
    unittest.main()
